//! graphify v0.9.107 `tests/test_rationale.py` (40 tests), the 28 whose assertion holds for
//! graphify-go v0.12.0: `pyRationale` (`python.go:721`), `pyDocstring`, `isAutogeneratedPython`,
//! `jsRationale` (`javascript.go:1441`), `addDocRef`, `addRationale` and `rationaleLabel`
//! (`extract.go:577-602`). Python tests write their source de-indented, as `textwrap.dedent` does.
//! Python ones are ignored on ihc.25, the JS/TS ones on ihc.26.
//!
//! Not ported (12), each false (or true by chance) for Go:
//! - `test_decorated_method_node_id_is_class_qualified`: asserts Python's method labels (`.baz()`)
//!   and ids (`_bar_baz`) and `build_from_json`; Go's labels (`Bar.baz()`) and ids differ by
//!   design (GOALS.md:83).
//! - `test_long_docstring_label_truncates_on_word_boundary`,
//!   `test_docstring_newline_and_indentation_collapsed_to_single_space`,
//!   `test_truncated_docstring_never_ends_with_bare_period`,
//!   `test_js_rationale_label_truncates_on_word_boundary`: Go's `rationaleLabel` cuts at 80 runes
//!   (no word boundary, no `…`) and turns each line break into one space but keeps the indent
//!   that follows it.
//! - `test_js_rationale_label_never_ends_with_bare_period_when_truncated`,
//!   `test_secret_not_left_as_prefix_when_label_truncates`: true for Go only because the 80-rune
//!   cut happens to land elsewhere (`th` of "the"; `gh` of "ghp_"); Go has no such rule.
//! - `test_comment_secret_redacted_from_rationale_label`,
//!   `test_docstring_secret_redacted_from_rationale_label`,
//!   `test_secret_absent_from_persisted_graph_json`: Go does not redact rationale labels (its
//!   only `[redacted]` is terraform attribute values, `terraform.go:199`).
//! - `test_commonlisp_docstring_secret_redacted`: no Common Lisp grammar in Go.
//! - `test_redact_rationale_labels_covers_any_extractor`: no `_redact_rationale_labels` in Go.

use crate::extract::Result;
use crate::extract::tests::util::extract_bytes;

fn py(src: &str) -> Result {
    extract_bytes("sample.py", src.as_bytes())
}

fn ts(src: &str) -> Result {
    extract_bytes("sample.ts", src.as_bytes())
}

fn rationale(r: &Result) -> Vec<&str> {
    r.nodes
        .iter()
        .filter(|n| n.file_type == "rationale")
        .map(|n| n.label.as_str())
        .collect()
}

fn doc_refs(r: &Result) -> Vec<&str> {
    r.nodes
        .iter()
        .filter(|n| n.file_type == "doc_ref")
        .map(|n| n.label.as_str())
        .collect()
}

fn any_contains(labels: &[&str], needle: &str) -> bool {
    labels.iter().any(|l| l.contains(needle))
}

#[test]
fn test_module_docstring_extracted() {
    let r = py(r#"
"""This module handles authentication because legacy sessions were insecure."""
def login(): pass
"#);
    let labels = rationale(&r);
    assert!(!labels.is_empty());
    assert!(any_contains(&labels, "authentication"), "{labels:?}");
}

#[test]
fn test_function_docstring_extracted() {
    let r = py(r#"
def process():
    """We use chunked processing here because the full dataset exceeds RAM."""
    pass
"#);
    assert!(any_contains(&rationale(&r), "chunked"));
}

#[test]
fn test_class_docstring_extracted() {
    let r = py(r#"
class Cache:
    """Chosen over Redis because we need zero external dependencies in the test env."""
    pass
"#);
    assert!(any_contains(&rationale(&r), "Redis"));
}

/// #3312: a leading `#!` shebang comment must not hide the module docstring that follows it.
#[test]
fn test_module_docstring_extracted_behind_shebang() {
    let r = py(concat!(
        "#!/usr/bin/env python3\n",
        "\"\"\"This module handles authentication because legacy sessions were insecure.\"\"\"\n",
        "def login(): pass\n"
    ));
    let at = r
        .nodes
        .iter()
        .find(|n| n.file_type == "rationale" && n.label.contains("authentication"))
        .expect("a rationale node about authentication");
    assert_eq!(at.source_location, "L2");
}

/// #3312: same bug, non-shebang trigger.
#[test]
fn test_module_docstring_extracted_behind_plain_comment() {
    let r = py(concat!(
        "# an ordinary leading comment, not a shebang\n",
        "\"\"\"This module handles authentication because legacy sessions were insecure.\"\"\"\n",
        "def login(): pass\n"
    ));
    assert!(any_contains(&rationale(&r), "authentication"));
}

/// #3312: a multi-line header: every leading comment must be skipped, not just the first one.
#[test]
fn test_module_docstring_extracted_behind_multiple_leading_comments() {
    let r = py(concat!(
        "#!/usr/bin/env python3\n",
        "# -*- coding: utf-8 -*-\n",
        "# Copyright 2026 Someone. All rights reserved.\n",
        "\"\"\"This module handles authentication because legacy sessions were insecure.\"\"\"\n",
        "def login(): pass\n"
    ));
    assert!(any_contains(&rationale(&r), "authentication"));
}

/// #3312: a comment as the first line of a function body must not hide its docstring.
#[test]
fn test_function_docstring_extracted_behind_leading_comment() {
    let r = py(r#"
def process():
    # a leading comment inside the function body
    """We use chunked processing here because the full dataset exceeds RAM."""
    pass
"#);
    assert!(any_contains(&rationale(&r), "chunked"));
}

/// #3312 follow-up: a leading comment with NO docstring after it must not fabricate a rationale
/// node from something else in the body.
#[test]
fn test_no_docstring_after_comment_extracts_nothing() {
    let r = py(concat!(
        "#!/usr/bin/env python3\n",
        "# just a comment, no docstring at all\n",
        "import os\n",
        "x = 1\n"
    ));
    assert!(rationale(&r).is_empty(), "{:?}", rationale(&r));
}

/// #3312 follow-up: a bare string literal that is NOT the first statement is not a docstring.
#[test]
fn test_non_first_statement_string_not_treated_as_docstring() {
    let r = py(concat!(
        "#!/usr/bin/env python3\n",
        "x = 1\n",
        "\"\"\"This string is not a docstring since it is not the first statement, long enough.\"\"\"\n"
    ));
    assert!(rationale(&r).is_empty(), "{:?}", rationale(&r));
}

#[test]
fn test_rationale_comment_extracted() {
    let r = py(r#"
def build():
    # NOTE: must run before compile() or linker will fail
    pass
"#);
    assert!(any_contains(&rationale(&r), "NOTE"));
}

#[test]
fn test_rationale_for_edges_present() {
    let r = py(r#"
"""Module docstring explaining the why."""
def foo():
    """Function docstring with rationale."""
    pass
"#);
    let n = r
        .edges
        .iter()
        .filter(|e| e.relation.as_str() == "rationale_for")
        .count();
    assert!(n >= 1, "{n} rationale_for edges");
}

/// Trivial docstrings under 20 chars should not become rationale nodes.
#[test]
fn test_short_docstring_ignored() {
    let r = py(r#"
def foo():
    """Constructor."""
    pass
"#);
    assert!(rationale(&r).is_empty(), "{:?}", rationale(&r));
}

#[test]
fn test_rationale_confidence_is_extracted() {
    let r = py(r#"
"""This module exists because we needed a standalone parser."""
def parse(): pass
"#);
    for e in r
        .edges
        .iter()
        .filter(|e| e.relation.as_str() == "rationale_for")
    {
        assert_eq!(e.confidence.as_str(), "EXTRACTED");
    }
}

#[test]
fn test_alembic_module_docstring_suppressed() {
    let r = py(r#"
"""initial schema

Revision ID: 0001abcd
Revises:
Create Date: 2023-01-01 00:00:00
"""
revision = "0001abcd"
down_revision = None
branch_labels = None

def upgrade():
    pass

def downgrade():
    pass
"#);
    assert!(
        !any_contains(&rationale(&r), "Revision ID"),
        "{:?}",
        rationale(&r)
    );
}

/// Function docstrings inside upgrade/downgrade should still be captured.
#[test]
fn test_alembic_function_docstrings_still_extracted() {
    let r = py(r#"
"""Revision ID: 0002 Revises: 0001"""
revision = "0002"
down_revision = "0001"

def upgrade():
    """Add users table because auth was added in this release."""
    pass

def downgrade():
    pass
"#);
    let labels = rationale(&r);
    // module docstring suppressed
    assert!(!any_contains(&labels, "Revision ID"), "{labels:?}");
    // function docstring still captured
    assert!(any_contains(&labels, "auth"), "{labels:?}");
}

/// A file with a `revision` variable but no Alembic markers keeps its docstring.
#[test]
fn test_non_migration_revision_var_not_suppressed() {
    let r = py(r#"
"""This module tracks document revisions because we need audit history."""
revision = 42

def get_revision(): pass
"#);
    assert!(any_contains(&rationale(&r), "audit history"));
}

#[test]
fn test_django_migration_module_docstring_suppressed() {
    let r = py(r#"
"""Add post_priority_config table."""
from django.db import migrations

class Migration(migrations.Migration):
    dependencies = [("myapp", "0001_initial")]
    operations = []
"#);
    assert!(
        !any_contains(&rationale(&r), "post_priority"),
        "{:?}",
        rationale(&r)
    );
}

#[test]
fn test_generated_file_module_docstring_suppressed() {
    let r = py(r#"
"""Generated by the protocol buffer compiler. DO NOT EDIT!"""
from google.protobuf import descriptor as _descriptor

class UserMessage:
    pass
"#);
    assert!(
        !rationale(&r)
            .iter()
            .any(|l| gostd::strings::to_lower(l).contains("protocol buffer")),
        "{:?}",
        rationale(&r)
    );
}

/// A docstring opening with a long, unbroken URL: the label must still carry real content.
#[test]
fn test_docstring_opening_with_unbroken_long_token_keeps_content() {
    let url = format!(
        "https://example.com/api/v3/settlements/{}/confirm",
        "a".repeat(60)
    );
    let docstring = format!("{url} documents the retry contract for this handler.");
    let r = py(&format!(
        "def call_endpoint():\n    \"\"\"{docstring}\"\"\"\n    pass\n"
    ));
    let labels = rationale(&r);
    let label = labels.first().expect("a rationale node");
    assert!(!label.is_empty() && *label != "\u{2026}", "{label}");
    assert!(label.starts_with("https://example.com/"), "{label}");
}

/// A docstring well under 80 chars passes through byte-for-byte.
#[test]
fn test_short_docstring_label_unchanged() {
    let docstring = "Splits the bearer token because some clients send a stray prefix.";
    let r = py(&format!(
        "def parse_token():\n    \"\"\"{docstring}\"\"\"\n    pass\n"
    ));
    assert_eq!(rationale(&r).first().copied(), Some(docstring));
}

#[test]
fn test_ordinary_rationale_untouched() {
    let r = py(r#"
def process():
    # WHY: chunked processing because the dataset exceeds RAM
    pass
"#);
    let labels = rationale(&r);
    assert!(
        any_contains(
            &labels,
            "chunked processing because the dataset exceeds RAM"
        ),
        "{labels:?}"
    );
    assert!(!any_contains(&labels, "[redacted]"), "{labels:?}");
}

// ── JS/TS rationale + doc-reference extraction ────────────────────────────────

#[test]
#[ignore = "graphify-rs-ihc.26"]
fn test_js_rationale_comment_extracted() {
    let r = ts(r#"
// NOTE: must run before compile() or the linker will fail
export function build(): void {}
"#);
    assert!(any_contains(&rationale(&r), "NOTE"));
}

#[test]
#[ignore = "graphify-rs-ihc.26"]
fn test_js_block_comment_rationale_extracted() {
    let r = ts(r#"
/**
 * WHY: retries are capped because the upstream rate-limits at 10 rps.
 */
export function fetchData(): void {}
"#);
    assert!(any_contains(&rationale(&r), "rate-limits"));
}

#[test]
#[ignore = "graphify-rs-ihc.26"]
fn test_js_adr_reference_extracted() {
    let r = ts(r#"
// Gateway pattern per ADR-0002; provider selection per ADR-0015.
export function route(): void {}
"#);
    let labels = doc_refs(&r);
    assert!(
        labels.contains(&"ADR-0002") && labels.contains(&"ADR-0015"),
        "{labels:?}"
    );
    let cites = r
        .edges
        .iter()
        .filter(|e| e.relation.as_str() == "cites")
        .count();
    assert_eq!(cites, 2);
}

#[test]
#[ignore = "graphify-rs-ihc.26"]
fn test_js_adr_reference_normalized_and_deduped() {
    let r = ts(r#"
// See ADR-11 for the trust boundary.
// ADR 0011 also governs the injection containment below.
export function guard(): void {}
"#);
    assert_eq!(doc_refs(&r), ["ADR-0011"]);
}

#[test]
#[ignore = "graphify-rs-ihc.26"]
fn test_js_adr_in_string_literal_not_extracted() {
    let r = ts(r#"
export const banner = "compliant with ADR-0099";
"#);
    assert!(doc_refs(&r).is_empty(), "{:?}", doc_refs(&r));
}

/// A `// WHY:` comment whose content is an unbroken long URL must not collapse to a content-free
/// label. The `WHY:` prefix always fits, so the invariant is that some real content survives.
#[test]
#[ignore = "graphify-rs-ihc.26"]
fn test_js_rationale_comment_opening_with_unbroken_long_token_keeps_content() {
    let url = format!(
        "https://example.com/api/v3/settlements/{}/confirm",
        "a".repeat(60)
    );
    let r = ts(&format!(
        "// WHY: {url} documents the retry contract for this handler.\nexport function fetchData(): void {{}}\n"
    ));
    let labels = rationale(&r);
    let label = labels.first().expect("a rationale node");
    assert!(!label.is_empty() && *label != "\u{2026}", "{label}");
    assert!(label.starts_with("WHY:"), "{label}");
}

/// A short `// NOTE:` comment passes through byte-for-byte.
#[test]
#[ignore = "graphify-rs-ihc.26"]
fn test_js_short_rationale_comment_unchanged() {
    let r = ts(r#"
// NOTE: must run before compile() or the linker will fail
export function build(): void {}
"#);
    assert_eq!(
        rationale(&r),
        ["NOTE: must run before compile() or the linker will fail"]
    );
}
